	 * Returns the SPKI Fingerprint suitable for use in pinning.  (See RFC 7469.)  An SPKI Fingerprint is defined as the output of a known cryptographic hash algorithm whose input is the DER-encoded ASN.1 representation of  the Subject Public Key Info (SPKI) of an X.509 certificate.  The ARG1 specifies the hash algorithm and may be sha256, sha384, sha512, sha1, md2, md5, haval, ripemd128, ripemd160,ripemd256, or ripemd320.   The ARG2 specifies the encoding, and may be base64, hex, or any of the encoding modes specified in the article at the link below.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#GetSpkiFingerprint
	 * @param ?string $hashAlg
	 * @param ?string $encoding
	 * @return ?string
	 */
	function spkiFingerprint($hashAlg,$encoding) {
		return CkCert_spkiFingerprint($this->_cPtr,$hashAlg,$encoding);
	}

	/**
	 * Returns a part of the certificate's subject by name or OID.  The ARG1 can be a part name, such as CN, O, OU, E, S, L, C, or SERIALNUMBER, or it can be an OID such as 2.5.4.3.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#GetSubjectPart
	 * @param ?string $partNameOrOid
	 * @return ?string
	 */
	function getSubjectPart($partNameOrOid) {
		return CkCert_getSubjectPart($this->_cPtr,$partNameOrOid);
	}

	/**
	 * Returns a part of the certificate's subject by name or OID.  The ARG1 can be a part name, such as CN, O, OU, E, S, L, C, or SERIALNUMBER, or it can be an OID such as 2.5.4.3.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#GetSubjectPart
	 * @param ?string $partNameOrOid
	 * @return ?string
	 */
	function subjectPart($partNameOrOid) {
		return CkCert_subjectPart($this->_cPtr,$partNameOrOid);
	}

	/**
	 * Returns the date/time this certificate becomes (or became) valid.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#GetValidFromDt
	 * @return ?CkDateTime
	 * @deprecated
	 */
	function GetValidFromDt() {
		return chilkat::_obj(CkCert_GetValidFromDt($this->_cPtr),'CkDateTime');
	}

	/**
	 * Returns the date/time this certificate becomes (or became) invalid.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#GetValidToDt
	 * @return ?CkDateTime
	 * @deprecated
	 */
	function GetValidToDt() {
		return chilkat::_obj(CkCert_GetValidToDt($this->_cPtr),'CkDateTime');
	}

	/**
	 * Returns an encoded hash of a particular part of the certificate.  The ARG1 may be one of the following:
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#HashOf
	 * @param ?string $part
	 * @param ?string $hashAlg
	 * @param ?string $encoding
	 * @return ?string
	 */
	function hashOf($part,$hashAlg,$encoding) {
		return CkCert_hashOf($this->_cPtr,$part,$hashAlg,$encoding);
	}

	/**
	 * Returns _TRUE_ if a private key associated with the certificate is available.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#HasPrivateKey
	 * @return bool
	 */
	function HasPrivateKey() {
		return CkCert_HasPrivateKey($this->_cPtr);
	}

	/**
	 * Returns _TRUE_ if certificate is ECDSA-based (i.e. has an ECDSA key).
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#IsEcdsa
	 * @return bool
	 */
	function IsEcdsa() {
		return CkCert_IsEcdsa($this->_cPtr);
	}

	/**
	 * Returns _TRUE_ if certificate is RSA-based (i.e. has an RSA key).
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#IsRsa
	 * @return bool
	 */
	function IsRsa() {
		return CkCert_IsRsa($this->_cPtr);
	}

	/**
	 * Links to the certificate's private key located on an HSM (smart card, token, or cloud HSM).  Once linked, the certificate can be used for signing where the signing occurs on the HSM.  See the example below for more detailed information.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LinkPkcs11
	 * @param CkPkcs11 $session
	 * @return bool
	 */
	function LinkPkcs11($session) {
		return CkCert_LinkPkcs11($this->_cPtr,$session);
	}

	/**
	 * This method searches for a certificate with the specified common name (CN) on different operating systems.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadByCommonName
	 * @param ?string $cn
	 * @return bool
	 */
	function LoadByCommonName($cn) {
		return CkCert_LoadByCommonName($this->_cPtr,$cn);
	}

	/**
	 * This method searches for a certificate with the specified email address on different operating systems.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadByEmailAddress
	 * @param ?string $emailAddress
	 * @return bool
	 */
	function LoadByEmailAddress($emailAddress) {
		return CkCert_LoadByEmailAddress($this->_cPtr,$emailAddress);
	}

	/**
	 * This method searches for a certificate with the specified issuer common name (ARG1) and serial number (ARG2)  on different operating systems.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadByIssuerAndSerialNumber
	 * @param ?string $issuerCN
	 * @param ?string $serialNumber
	 * @return bool
	 */
	function LoadByIssuerAndSerialNumber($issuerCN,$serialNumber) {
		return CkCert_LoadByIssuerAndSerialNumber($this->_cPtr,$issuerCN,$serialNumber);
	}

	/**
	 * This method searches for a certificate containing a subject part matching the ARG1 and ARG2.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadBySubjectOid
	 * @param ?string $oid
	 * @param ?string $value
	 * @return bool
	 */
	function LoadBySubjectOid($oid,$value) {
		return CkCert_LoadBySubjectOid($this->_cPtr,$oid,$value);
	}

	/**
	 * This method searches for a certificate with the specified ARG1.  The ARG1 is passed as a string using the encoding specified by ARG2 (such as base64, hex, etc.).
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadByThumbprint
	 * @param ?string $thumbprint
	 * @param ?string $encoding
	 * @return bool
	 */
	function LoadByThumbprint($thumbprint,$encoding) {
		return CkCert_LoadByThumbprint($this->_cPtr,$thumbprint,$encoding);
	}

	/**
	 * Loads an ASN.1 or DER encoded certificate represented in a Base64 string.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadFromBase64
	 * @param ?string $encodedCert
	 * @return bool
	 */
	function LoadFromBase64($encodedCert) {
		return CkCert_LoadFromBase64($this->_cPtr,$encodedCert);
	}

	/**
	 * Loads an X.509 certificate from data contained in ARG1.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadFromBd
	 * @param CkBinData $certBytes
	 * @return bool
	 */
	function LoadFromBd($certBytes) {
		return CkCert_LoadFromBd($this->_cPtr,$certBytes);
	}

	/**
	 * Loads an X.509 certificate from ASN.1 DER encoded bytes.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadFromBinary
	 * @param CkByteData $data
	 * @return bool
	 */
	function LoadFromBinary($data) {
		return CkCert_LoadFromBinary($this->_cPtr,$data);
	}

	/**
	 * Loads a certificate from a .cer, .crt, .p7b, or .pem file. This method accepts certificates from files in any of the following formats: 1. DER encoded binary X.509 (.CER) 2. Base-64 encoded X.509 (.CER) 3. Cryptographic Message Syntax Standard - PKCS #7 Certificates (.P7B) 4. PEM format This method decodes the certificate based on the contents if finds within the file, and not based on the file extension. If your certificate is in a file having a different extension, try loading it using this method before assuming it won't work. This method does not load .p12 or .pfx (PKCS #12) files.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadFromFile
	 * @param ?string $path
	 * @return bool
	 */
	function LoadFromFile($path) {
		return CkCert_LoadFromFile($this->_cPtr,$path);
	}

	/**
	 * Important: It's important to set the SmartCardPin property before calling this method.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadFromSmartcard
	 * @param ?string $certSpec
	 * @return bool
	 */
	function LoadFromSmartcard($certSpec) {
		return CkCert_LoadFromSmartcard($this->_cPtr,$certSpec);
	}

	/**
	 * Loads the certificate from a PEM string.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadPem
	 * @param ?string $strPem
	 * @return bool
	 */
	function LoadPem($strPem) {
		return CkCert_LoadPem($this->_cPtr,$strPem);
	}

	/**
	 * Loads the certificate from the PFX contained in ARG1.   Note: If the PFX contains multiple certificates, the 1st certificate in the PFX is loaded.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadPfxBd
	 * @param CkBinData $pfxData
	 * @param ?string $password
	 * @return bool
	 */
	function LoadPfxBd($pfxData,$password) {
		return CkCert_LoadPfxBd($this->_cPtr,$pfxData,$password);
	}

	/**
	 * Loads a PFX from an in-memory image of a PFX file.   Note: If the PFX contains multiple certificates, the 1st certificate in the PFX is loaded.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadPfxData
	 * @param CkByteData $pfxData
	 * @param ?string $password
	 * @return bool
	 */
	function LoadPfxData($pfxData,$password) {
		return CkCert_LoadPfxData($this->_cPtr,$pfxData,$password);
	}

	/**
	 * Loads a PFX file.  Note: If the PFX contains multiple certificates, the 1st certificate in the PFX is loaded.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadPfxFile
	 * @param ?string $pfxPath
	 * @param ?string $password
	 * @return bool
	 */
	function LoadPfxFile($pfxPath,$password) {
		return CkCert_LoadPfxFile($this->_cPtr,$pfxPath,$password);
	}

	/**
	 * Loads the certificate from a completed asynchronous task.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#LoadTaskResult
	 * @param CkTask $task
	 * @return bool
	 */
	function LoadTaskResult($task) {
		return CkCert_LoadTaskResult($this->_cPtr,$task);
	}

	/**
	 * Converts a PEM file to a DER file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#PemFileToDerFile
	 * @param ?string $fromPath
	 * @param ?string $toPath
	 * @return bool
	 */
	function PemFileToDerFile($fromPath,$toPath) {
		return CkCert_PemFileToDerFile($this->_cPtr,$fromPath,$toPath);
	}

	/**
	 * Saves a certificate object to a .cer file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#SaveToFile
	 * @param ?string $path
	 * @return bool
	 */
	function SaveToFile($path) {
		return CkCert_SaveToFile($this->_cPtr,$path);
	}

	/**
	 * Provides information for a cloud signing service to do the signing via a remote signing server.  Current supported services are AWS KMS, Azure Key Vault, and ARSS (Aruba Remote Signing Service).  See the examples below.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#SetCloudSigner
	 * @param CkJsonObject $json
	 * @return bool
	 */
	function SetCloudSigner($json) {
		return CkCert_SetCloudSigner($this->_cPtr,$json);
	}

	/**
	 * Creates an asynchronous task to call the SetCloudSigner method with the arguments provided.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#SetCloudSignerAsync
	 * @param CkJsonObject $json
	 * @return ?CkTask
	 */
	function SetCloudSignerAsync($json) {
		return chilkat::_obj(CkCert_SetCloudSignerAsync($this->_cPtr,$json),'CkTask');
	}

	/**
	 * Initializes the certificate object from a base64 encoded string representation of the certificate's binary DER format.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#SetFromEncoded
	 * @param ?string $encodedCert
	 * @return bool
	 */
	function SetFromEncoded($encodedCert) {
		return CkCert_SetFromEncoded($this->_cPtr,$encodedCert);
	}

	/**
	 * Used to associate a private key with the certificate for subsequent (PKCS7) signature creation or decryption.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#SetPrivateKey
	 * @param CkPrivateKey $privKey
	 * @return bool
	 */
	function SetPrivateKey($privKey) {
		return CkCert_SetPrivateKey($this->_cPtr,$privKey);
	}

	/**
	 * Same as SetPrivateKey, but the key is provided in unencrypted PEM format.  (Note: The ARG1 is not a file path, it is the actual  PEM text.)
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#SetPrivateKeyPem
	 * @param ?string $privKeyPem
	 * @return bool
	 */
	function SetPrivateKeyPem($privKeyPem) {
		return CkCert_SetPrivateKeyPem($this->_cPtr,$privKeyPem);
	}

	/**
	 * Unload the certificate, which could mean closing a PKCS11 session if the certificate was loaded from a smart card.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#Unload
	 * @return bool
	 */
	function Unload() {
		return CkCert_Unload($this->_cPtr);
	}

	/**
	 * This is an open-ended method to accomodate uploading the private key to a cloud service, such as AWS KMS, or Azure Key Vault.  For details, see the examples below.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#UploadToCloud
	 * @param CkJsonObject $jsonIn
	 * @param CkJsonObject $jsonOut
	 * @return bool
	 */
	function UploadToCloud($jsonIn,$jsonOut) {
		return CkCert_UploadToCloud($this->_cPtr,$jsonIn,$jsonOut);
	}

	/**
	 * Creates an asynchronous task to call the UploadToCloud method with the arguments provided.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#UploadToCloudAsync
	 * @param CkJsonObject $jsonIn
	 * @param CkJsonObject $jsonOut
	 * @return ?CkTask
	 */
	function UploadToCloudAsync($jsonIn,$jsonOut) {
		return chilkat::_obj(CkCert_UploadToCloudAsync($this->_cPtr,$jsonIn,$jsonOut),'CkTask');
	}

	/**
	 * Adds an XML certificate vault to the object's internal list of sources to be searched for certificates for help in building certificate chains and verifying the certificate signature to the trusted root.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#UseCertVault
	 * @param CkXmlCertVault $vault
	 * @return bool
	 */
	function UseCertVault($vault) {
		return CkCert_UseCertVault($this->_cPtr,$vault);
	}

	/**
	 * Verifies the certificate signature, as well as the signatures of all certificates in the chain of authentication to the trusted root.  Returns _TRUE_ if all signatures are verified to the trusted root.  Otherwise returns _FALSE_.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#VerifySignature
	 * @return bool
	 */
	function VerifySignature() {
		return CkCert_VerifySignature($this->_cPtr);
	}

	/**
	 * Returns the base64 representation of an X509PKIPathv1 containing just the calling certificate.  This is typically used in an X.509 Binary Security Token.  It is a PKIPath that contains an ordered list of X.509 public certificates packaged in a PKIPath. The X509PKIPathv1 token type may be used to represent a certificate path.  (This is sometimes used in XAdES signatures.)
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCertRef.html#X509PKIPathv1
	 * @return ?string
	 */
	function x509PKIPathv1() {
		return CkCert_x509PKIPathv1($this->_cPtr);
	}
}
